pub type Person = { name: Str; age: Int; }

fn parse_person(raw: Str) -> Person {
  let parts = raw.split(',');
  return Person{ name: parts[0], age: parts[1].parse_int().unwrap() };
}

fn is_adult(p: &Person) -> Bool { return p.age >= 18; }

fn main() -> Int {
  let data = Vec[Str]();
  data.push("Alice,30"); data.push("Bob,15"); data.push("Charlie,25");

  var adults = 0;
  for raw in data {
    let person = parse_person(raw);
    if is_adult(&person) { adults = adults + 1; }
  }
  return adults;
}
